INSERT INTO `assessment_templates` VALUES
(1,'JAWS workstation assessment','Screen Reader','Windows laptop, 16GB RAM, external keyboard','JAWS (current version)','Areas evaluated:\n- Current typing/keyboard proficiency\n- Screen reader experience level\n- Primary computer tasks required (work/school/daily living)\n- Recommended training hours and focus areas\n\nFindings:\n\nRecommendations:','2026-07-21 17:19:51'),
(2,'Low vision / magnification assessment','Magnification','Windows laptop, 24in external monitor','ZoomText / Fusion (current version)','Areas evaluated:\n- Functional visual acuity at screen\n- Preferred magnification level and color settings\n- Lighting and ergonomic needs\n- Task endurance and fatigue factors\n\nFindings:\n\nRecommendations:','2026-07-21 17:19:51'),
(3,'Braille technology assessment','Braille Display','Refreshable braille display (40-cell), paired device','Device firmware + screen reader (current)','Areas evaluated:\n- Braille reading fluency (grade 1/2/UEB)\n- Device pairing and navigation skills\n- Note-taking and document workflows\n\nFindings:\n\nRecommendations:','2026-07-21 17:19:51'),
(4,'iOS accessibility assessment','Other','iPhone (client device)','iOS (current version), VoiceOver/Zoom','Areas evaluated:\n- Current gesture proficiency\n- Communication, navigation, and productivity app needs\n- Braille screen input / external keyboard needs\n\nFindings:\n\nRecommendations:','2026-07-21 17:19:51'),
(5,'Rehab teaching / independent living assessment','Independent Living Skills','Home environment walkthrough','N/A','Areas evaluated:\n- Kitchen safety and meal preparation\n- Home organization and labeling needs\n- Medication and financial management\n- Laundry and home management routines\n- Lighting, contrast, and home modifications\n\nFindings:\n\nRecommendations:','2026-07-23 15:49:41'),
(6,'Braille literacy assessment','Braille Literacy','Slate & stylus / Perkins brailler','N/A','Areas evaluated:\n- Current braille knowledge (letters, numbers, contractions)\n- Tactile discrimination readiness\n- Reading and writing goals for daily living or employment\n\nFindings:\n\nRecommendations:','2026-07-23 15:49:41'),
(7,'Low vision functional assessment','Low Vision Devices','Client-prescribed magnifiers/monoculars','N/A','Areas evaluated:\n- Functional vision for near and distance tasks\n- Current device use and technique\n- Lighting and contrast needs\n- Priority daily tasks (mail, labels, mobility signage)\n\nFindings:\n\nRecommendations:','2026-07-23 15:49:41'),
(8,'Rehabilitation technology / worksite assessment','Rehabilitation Technology','Employer worksite walkthrough; measurements of workstation','Task-specific software as used on the job','Areas evaluated:\n- Essential job functions and physical/sensory demands\n- Current workstation ergonomics (seating, monitor, input, lighting)\n- Adaptive equipment and input device needs\n- Assistive listening / alerting needs\n- Employer accommodation feasibility and cost\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(9,'Environmental control & smart-home assessment','Rehabilitation Technology','Home walkthrough; smart speaker/hub, smart plugs','Voice assistant + smart-home app (current)','Areas evaluated:\n- Daily tasks limited by current environment\n- Devices to control (lighting, thermostat, doors, appliances, comms)\n- Network and hub compatibility\n- Client comfort with voice vs. switch/app control\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(10,'OCR & reading technology assessment','Rehabilitation Technology','Smartphone/tablet or standalone reading machine; scanner','OCR app / reading software (current)','Areas evaluated:\n- Volume and types of print materials encountered\n- Speed and accuracy needs (mail, bills, work documents)\n- Standalone vs. app-based reading preference\n- Document-conversion and file-organization needs\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(11,'AI vision & wearable technology assessment','Rehabilitation Technology','Smartphone; wearable/smart glasses if applicable','Seeing AI / Envision / Aira / Be My Eyes (current)','Areas evaluated:\n- Real-world tasks needing visual information (text, currency, products, scenes)\n- Hands-free / wearable vs. handheld preference\n- Connectivity and privacy considerations for remote assistance\n- When to use AI tools vs. human assistance\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(12,'Accessible GPS & orientation technology assessment','Rehabilitation Technology','Smartphone; bone-conduction headset if applicable','BlindSquare / Soundscape / Nearby Explorer (current)','Areas evaluated:\n- Routine travel routes and current O&M skills\n- Familiar vs. unfamiliar environment needs\n- App/device preferences and audio delivery\n- Integration with white cane / guide dog travel\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(13,'STEM & tactile graphics access assessment','Rehabilitation Technology','Braille embosser / tactile graphics tools; computer','Accessible math editor + braille translation software','Areas evaluated:\n- Math/science tasks required for school or work\n- Nemeth braille vs. accessible math editor proficiency\n- Tactile graphics interpretation and production needs\n- Embosser and materials availability\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(14,'Electronic video magnifier (CCTV) assessment','Low Vision Devices','Desktop and/or portable electronic magnifier','Device firmware (current)','Areas evaluated:\n- Near, intermediate, and distance magnification tasks\n- Preferred magnification range, contrast, and color modes\n- Desktop vs. portable use scenarios\n- Ergonomics and workspace fit\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(15,'Deaf-blind assistive technology assessment','Rehabilitation Technology','Refreshable braille display; screen braille communicator','Screen reader + haptic/notification software','Areas evaluated:\n- Combined vision and hearing functional levels\n- Preferred communication modes (braille, haptics, print/large print)\n- Device pairing and alerting needs\n- Communication partner and community access needs\n\nFindings:\n\nRecommendations:','2026-09-29 19:38:11'),
(16,'Vocational technology needs assessment','Other','Client work tasks; current devices','Job-relevant software','Areas evaluated:\n- Vocational goal and essential job functions\n- Current technology skills and gaps\n- Recommended AT and training plan\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(17,'Computer skills baseline assessment','Screen Reader','Windows/Mac computer','Current AT','Areas evaluated:\n- Keyboard and navigation proficiency\n- File, email, and document skills\n- Screen reader/magnification proficiency\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(18,'Microsoft 365 workplace assessment','Screen Reader','Work computer','Microsoft 365 + AT','Areas evaluated:\n- Word, Excel, Outlook, Teams tasks required\n- Current proficiency and training needs\n- Accessible document production needs\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(19,'Google Workspace & Chromebook accessibility assessment','Screen Reader','Chromebook or Chrome','ChromeVox / Select-to-Speak','Areas evaluated:\n- Docs, Sheets, Gmail, Drive tasks\n- ChromeVox vs. other AT preference\n- Device and account setup\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(20,'macOS VoiceOver assessment','Screen Reader','Mac','macOS + VoiceOver','Areas evaluated:\n- Essential Mac tasks\n- VoiceOver rotor and commander proficiency\n- Transfer from prior AT\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(21,'Orientation & mobility assessment','Independent Living Skills','Long white cane; low-vision devices','N/A','Areas evaluated:\n- Travel skills and confidence (indoor/outdoor/transit)\n- Cane technique and landmark use\n- Street crossings and route planning\n- Functional vision affecting travel\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(22,'Visual efficiency & low-vision skills assessment','Low Vision Devices','Graded print; task lighting','N/A','Areas evaluated:\n- Field use and eccentric-viewing readiness\n- Scanning, tracking, and localization\n- Print size, contrast, and lighting\n- Endurance for near/distance tasks\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(23,'Diabetes & health self-management assessment','Independent Living Skills','Accessible glucometer; insulin aids','N/A','Areas evaluated:\n- Current health-management routine and safety\n- Accessible testing, medication, insulin techniques\n- Supply labeling and provider communication\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(24,'Recreation & leisure assessment','Independent Living Skills','Activity materials','Accessible apps/tools','Areas evaluated:\n- Desired leisure, fitness, social activities\n- Barriers and adapted techniques/tools\n- Community recreation and transportation\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(25,'Digital literacy & online safety assessment','Other','Client computer/phone','Password manager; browser','Areas evaluated:\n- Online banking, shopping, account management\n- Password and phishing awareness\n- Privacy and safe-disclosure habits\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(26,'Communication technology assessment','Other','Smartphone; adapted phone','Accessible calling/messaging apps','Areas evaluated:\n- Phone, video, and messaging needs\n- Contact, voicemail, correspondence management\n- Preferred modalities and tools\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(27,'Employment readiness & soft-skills assessment','Other','N/A','N/A','Areas evaluated:\n- Communication, teamwork, professionalism\n- Interview and disclosure readiness\n- Workplace supports needed\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(28,'Job-site & worksite accommodation assessment','Rehabilitation Technology','Employer worksite walkthrough','Job-specific software','Areas evaluated:\n- Essential functions and demands\n- Workstation ergonomics and adaptive input\n- Accommodation feasibility and cost\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(29,'Transportation & travel-training assessment','Independent Living Skills','Transit info; mobility aids','Accessible transit apps','Areas evaluated:\n- Current travel skills and routes\n- Transit, paratransit, rideshare needs\n- Trip-planning and safety\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(30,'Benefits & work-incentives assessment','Other','N/A','N/A','Areas evaluated:\n- Current benefits and earnings concerns\n- Applicable work incentives\n- Reporting and savings planning needs\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34'),
(31,'Postsecondary education readiness assessment','Other','Student devices','LMS + AT','Areas evaluated:\n- Accessible notetaking and study skills\n- Accessible materials and LMS access\n- Accommodations and time management\n\nFindings:\n\nRecommendations:','2026-09-30 13:15:34');
INSERT INTO `service_bundles` VALUES
(1,'Pre-ETS Core Services','Pre-ETS','Job Exploration Counseling (Pre-ETS);Work-Based Learning Experiences (Pre-ETS);Counseling on Postsecondary Opportunities (Pre-ETS);Workplace Readiness Training (Pre-ETS);Instruction in Self-Advocacy (Pre-ETS)','The five required pre-employment transition services under Section 113 / 34 CFR 361.48(a)',1,'2026-09-26 11:15:52'),
(2,'Pre-ETS Rehab Tech','Pre-ETS','Job Exploration Counseling (Pre-ETS);Work-Based Learning Experiences (Pre-ETS);Counseling on Postsecondary Opportunities (Pre-ETS);Workplace Readiness Training (Pre-ETS);Instruction in Self-Advocacy (Pre-ETS);Rehabilitation Technology','Pre-ETS services delivered alongside rehabilitation technology — billed under the Pre-ETS Rehab Tech program label',1,'2026-09-26 11:15:52'),
(3,'Pre-ETS Workplace Readiness & Self-Advocacy','Pre-ETS','Workplace Readiness Training (Pre-ETS);Instruction in Self-Advocacy (Pre-ETS)','Focused workshop pairing commonly delivered as a group series',1,'2026-09-26 11:15:52'),
(4,'Tech Referral','VR','Rehabilitation Technology;Disability-Related Skills Training','Standard technology referral: rehabilitation technology plus disability-related skills training',1,'2026-09-26 11:15:52'),
(5,'AT Evaluation & Recommendation','VR','Assessment;Rehabilitation Technology','Assistive technology assessment leading to equipment recommendation',1,'2026-09-26 11:15:52'),
(6,'Independent Living / Rehab Teaching','VR','Disability-Related Skills Training;VR Counseling and Guidance','Rehabilitation teaching with adjustment counseling as needed',1,'2026-09-26 11:15:52'),
(7,'Counseling & Guidance','VR','VR Counseling and Guidance;Benefits Counseling','Adjustment counseling with benefits counseling as needed',1,'2026-09-26 11:15:52'),
(8,'Employment Preparation','VR','Job Readiness Training;Disability-Related Skills Training;Job Search Assistance','Job readiness with disability-related skills and job search support',1,'2026-09-26 11:15:52'),
(9,'Job Readiness & Placement','VR','Job Readiness Training;Job Search Assistance;Job Placement Assistance','Preparing for, finding, and landing a job — resume, interview, and placement work',1,'2026-09-29 12:34:53'),
(10,'Supported Employment','VR','Supported Employment Services;Job Placement Assistance;Short-Term Job Supports','Ongoing on-the-job support for clients who need coaching to maintain competitive integrated employment',1,'2026-09-29 12:34:53'),
(11,'Customized Employment','VR','Customized Employment Services;Job Placement Assistance;Short-Term Job Supports','Individualized job carving and negotiation with an employer, with placement and short-term supports',1,'2026-09-29 12:34:53'),
(12,'On-the-Job Training Support','VR','On-the-Job Training;Short-Term Job Supports;Job Readiness Training','Supporting a client through an employer-based OJT arrangement',1,'2026-09-29 12:34:53'),
(13,'Workplace AT & Job Retention','VR','Rehabilitation Technology;Short-Term Job Supports','Assistive technology setup and training at the job site to keep an employed client working',1,'2026-09-29 12:34:53'),
(14,'Self-Employment Support','VR','Technical Assistance Services;Benefits Counseling;VR Counseling and Guidance','Technical assistance for a self-employment or small-business plan, with benefits and VR guidance',1,'2026-09-29 12:34:53'),
(15,'Assessment & Counseling Intake','VR','Assessment;VR Counseling and Guidance','Initial evaluation and counseling to determine needs and plan services',1,'2026-09-29 12:34:53'),
(16,'Benefits & Work Incentives Counseling','VR','Benefits Counseling;Information and Referral Services;VR Counseling and Guidance','How working affects SSI/SSDI and other benefits, with referrals to related resources',1,'2026-09-29 12:34:53'),
(17,'Braille & Literacy Training','VR','Disability-Related Skills Training;Basic Academic Remedial or Literacy Training','Braille instruction and adaptive literacy skills',1,'2026-09-29 12:34:53'),
(18,'College & Training AT Support','VR','Rehabilitation Technology;Disability-Related Skills Training;Reader Services','Assistive technology, study skills, and reader support for postsecondary students',1,'2026-09-29 12:34:53'),
(19,'Youth Transition (VR)','VR','Job Readiness Training;VR Counseling and Guidance;Disability-Related Skills Training','Older youth already on a VR plan (not Pre-ETS): work readiness, counseling, and adjustment skills',1,'2026-09-29 12:34:53'),
(20,'Comprehensive AT Program','VR','Assessment;Rehabilitation Technology;Disability-Related Skills Training;Job Readiness Training','Full cycle: AT evaluation, device training, adjustment skills, and employment preparation',1,'2026-09-29 12:34:53'),
(21,'Reader & Interpreter Services','Any','Reader Services;Interpreter Services','Reader or interpreter services billed as a standalone support',1,'2026-09-29 12:34:53');
INSERT INTO `groups` VALUES
(1,'Administrators','Full access to everything, including user and system management','clients;reports;referrals;schedule;equipment;billing;analytics;templates;admin;programs;procurement',0,'2026-09-26 11:27:03'),
(2,'Instructors','Field staff: their own caseload, scheduling, referrals, equipment, and reports','clients;reports;referrals;schedule;equipment',1,'2026-09-26 11:27:03'),
(3,'Billing & Reporting','Invoices, agency reports, analytics, and full read and write access to every client record (not limited to a caseload)','clients;billing;analytics',0,'2026-09-26 11:27:03'),
(4,'Front Desk','Referral intake and scheduling only','referrals;schedule',0,'2026-09-26 11:27:03');
INSERT INTO `assessment_instruments` VALUES
(1,'AT Skills Checklist','Baseline and outcome rating of core assistive-technology computer skills. Each item is scored 0 (unable) to 4 (independent).',0,4,NULL,1,NULL,1,'2026-09-30 15:10:09'),
(2,'Functional Vision Skills','Functional use of vision for everyday near, distance, and travel tasks. Scored 0-4.',0,4,NULL,1,NULL,1,'2026-09-30 15:10:09'),
(3,'Orientation & Mobility Skills','Travel and orientation skills for safe, independent movement. Scored 0-4.',0,4,NULL,1,NULL,1,'2026-09-30 15:10:09'),
(4,'Independent Living Skills','Daily living skills for independence at home and in the community. Scored 0-4.',0,4,NULL,1,NULL,1,'2026-09-30 15:10:09'),
(5,'AT Device Satisfaction (1-5)','User satisfaction with an assistive device and the services around it. Re-administer to show change. Original items; replace with a licensed instrument\'s wording if your program uses one.',1,5,'1=1 Not satisfied at all;2=2 Not very satisfied;3=3 More or less satisfied;4=4 Quite satisfied;5=5 Very satisfied',1,'Satisfaction',1,'2026-09-30 20:44:26'),
(6,'Psychosocial Impact of AT (-3..+3)','How the assistive technology has changed the user\'s competence, adaptability and self-esteem. Rate each: since using the device, this has gotten worse (-) / no change (0) / better (+). Original items.',-3,3,'-3=-3 Much worse;-2=-2 Worse;-1=-1 Slightly worse;0=0 No change;1=+1 Slightly better;2=+2 Better;3=+3 Much better',1,'Psychosocial impact',1,'2026-09-30 20:44:26'),
(7,'Person-Technology Match Check (0-4)','A readiness/fit checklist to judge how well a device matches the person and their environments before and after provision. Original items.',0,4,'0=0 Not at all;1=1 Slightly;2=2 Somewhat;3=3 Mostly;4=4 Fully',1,'Match',1,'2026-09-30 20:44:26');
