-- AT service workflows. Safe to rerun; no existing records are rewritten.
CREATE TABLE IF NOT EXISTS at_records (
 id INT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,
 kind VARCHAR(32) NOT NULL,
 client_id INT UNSIGNED NULL,
 track_id INT UNSIGNED NULL,
 equipment_id INT UNSIGNED NULL,
 staff_id INT UNSIGNED NULL,
 parent_id INT UNSIGNED NULL,
 title VARCHAR(190) NOT NULL,
 status VARCHAR(40) NOT NULL,
 due_date DATE NULL,
 details LONGTEXT NOT NULL,
 source_key VARCHAR(120) NULL,
 version INT UNSIGNED NOT NULL DEFAULT 1,
 created_by INT UNSIGNED NULL,
 created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 UNIQUE KEY at_source (source_key),
 KEY at_kind_due (kind, status, due_date),
 KEY at_client (client_id),
 CONSTRAINT at_client_fk FOREIGN KEY (client_id) REFERENCES clients(id) ON DELETE CASCADE,
 CONSTRAINT at_track_fk FOREIGN KEY (track_id) REFERENCES training_tracks(id) ON DELETE SET NULL,
 CONSTRAINT at_equipment_fk FOREIGN KEY (equipment_id) REFERENCES equipment(id) ON DELETE SET NULL,
 CONSTRAINT at_staff_fk FOREIGN KEY (staff_id) REFERENCES users(id) ON DELETE SET NULL,
 CONSTRAINT at_parent_fk FOREIGN KEY (parent_id) REFERENCES at_records(id) ON DELETE CASCADE,
 CONSTRAINT at_details_json CHECK (JSON_VALID(details))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS at_reminders (
 record_id INT UNSIGNED NOT NULL,
 due_date DATE NOT NULL,
 user_id INT UNSIGNED NOT NULL,
 PRIMARY KEY (record_id, due_date, user_id),
 CONSTRAINT at_reminder_record_fk FOREIGN KEY (record_id) REFERENCES at_records(id) ON DELETE CASCADE,
 CONSTRAINT at_reminder_user_fk FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Workflow and AI quality features. Additive and safe to run again.
ALTER TABLE ai_usage ADD COLUMN IF NOT EXISTS succeeded tinyint(1) DEFAULT NULL,
 ADD COLUMN IF NOT EXISTS duration_ms int unsigned DEFAULT NULL,
 ADD COLUMN IF NOT EXISTS truncated tinyint(1) NOT NULL DEFAULT 0;
CREATE TABLE IF NOT EXISTS ai_feedback (
 id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,
 usage_id int unsigned NOT NULL,
 user_id int unsigned NOT NULL,
 rating varchar(24) NOT NULL,
 comment varchar(1000) NOT NULL DEFAULT '',
 created_at datetime NOT NULL DEFAULT current_timestamp(),
 UNIQUE KEY usage_user (usage_id,user_id),
 CONSTRAINT fk_feedback_usage FOREIGN KEY (usage_id) REFERENCES ai_usage(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS referral_waitlist (
 referral_id int unsigned NOT NULL PRIMARY KEY,
 status varchar(24) NOT NULL DEFAULT 'Waiting',
 expertise varchar(500) NOT NULL DEFAULT '',
 languages varchar(190) NOT NULL DEFAULT '',
 areas varchar(190) NOT NULL DEFAULT '',
 modality varchar(24) NOT NULL DEFAULT 'Both',
 availability varchar(1000) NOT NULL DEFAULT '',
 followup_date date DEFAULT NULL,
 version int unsigned NOT NULL DEFAULT 1,
 created_at datetime NOT NULL DEFAULT current_timestamp(),
 updated_at datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
 CONSTRAINT fk_waitlist_referral FOREIGN KEY (referral_id) REFERENCES referrals(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS homework_practice (
 id int unsigned NOT NULL AUTO_INCREMENT PRIMARY KEY,
 homework_id int unsigned NOT NULL,
 minutes smallint unsigned NOT NULL,
 difficulty varchar(24) NOT NULL,
 notes varchar(2000) NOT NULL DEFAULT '',
 staff_feedback varchar(2000) DEFAULT NULL,
 feedback_by int(10) unsigned DEFAULT NULL,
 feedback_at datetime DEFAULT NULL,
 request_key char(32) NOT NULL,
 created_at datetime NOT NULL DEFAULT current_timestamp(),
 UNIQUE KEY practice_request (request_key),
 KEY homework_date (homework_id,created_at),
 CONSTRAINT fk_practice_homework FOREIGN KEY (homework_id) REFERENCES homework(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS documentation_reviews (
 note_id int unsigned NOT NULL PRIMARY KEY,
 fingerprint char(64) NOT NULL,
 reviewer_id int unsigned NOT NULL,
 rationale varchar(1000) NOT NULL,
 reviewed_at datetime NOT NULL DEFAULT current_timestamp(),
 CONSTRAINT fk_review_note FOREIGN KEY (note_id) REFERENCES client_notes(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `invoice_payments` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `invoice_id` int(10) unsigned NOT NULL,
  `kind` enum('payment','writeoff') NOT NULL DEFAULT 'payment',
  `amount` decimal(10,2) NOT NULL,
  `received_on` date NOT NULL,
  `reference` varchar(80) DEFAULT NULL,
  `note` varchar(255) DEFAULT NULL,
  `recorded_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `qbo_id` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `invoice_qbo_payment` (`invoice_id`,`qbo_id`),
  KEY `invoice_id` (`invoice_id`),
  CONSTRAINT `fk_payment_invoice` FOREIGN KEY (`invoice_id`) REFERENCES `invoices` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `client_closures` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `status` varchar(40) NOT NULL,
  `reason` varchar(60) NOT NULL,
  `note` varchar(255) DEFAULT NULL,
  `employed` tinyint(1) DEFAULT NULL,
  `employer` varchar(190) DEFAULT NULL,
  `job_title` varchar(120) DEFAULT NULL,
  `job_start` date DEFAULT NULL,
  `hours_per_week` decimal(5,2) DEFAULT NULL,
  `hourly_wage` decimal(8,2) DEFAULT NULL,
  `independence_outcome` varchar(500) DEFAULT NULL,
  `closed_by` int(10) unsigned DEFAULT NULL,
  `closed_at` datetime NOT NULL DEFAULT current_timestamp(),
  `at_recommended` smallint(5) unsigned DEFAULT NULL,
  `at_acquired` smallint(5) unsigned DEFAULT NULL,
  `at_in_use` tinyint(1) DEFAULT NULL,
  `at_note` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_closure_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `client_note_revisions` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `note_id` int(10) unsigned NOT NULL,
  `client_id` int(10) unsigned NOT NULL,
  `track_id` int(10) unsigned DEFAULT NULL,
  `note_type` varchar(40) NOT NULL,
  `note_format` varchar(10) NOT NULL DEFAULT 'free',
  `subject` varchar(255) NOT NULL,
  `body` text NOT NULL,
  `birp_behavior` text DEFAULT NULL,
  `birp_intervention` text DEFAULT NULL,
  `birp_response` text DEFAULT NULL,
  `birp_plan` text DEFAULT NULL,
  `version_written_at` datetime DEFAULT NULL,
  `version_written_by` int(10) unsigned DEFAULT NULL,
  `replaced_at` datetime NOT NULL DEFAULT current_timestamp(),
  `replaced_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `note_id` (`note_id`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_note_rev_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `client_releases` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `signer_role` varchar(20) NOT NULL DEFAULT 'Client',
  `signer_name` varchar(120) NOT NULL,
  `signer_email` varchar(190) DEFAULT NULL,
  `recipient_type` varchar(40) NOT NULL,
  `recipient_name` varchar(190) NOT NULL,
  `recipient_email` varchar(190) DEFAULT NULL,
  `info_scope` varchar(500) NOT NULL,
  `purpose` varchar(255) NOT NULL,
  `method` varchar(10) NOT NULL DEFAULT 'Email',
  `token` char(48) DEFAULT NULL,
  `sent_at` datetime NOT NULL DEFAULT current_timestamp(),
  `created_by` int(10) unsigned DEFAULT NULL,
  `signed_at` datetime DEFAULT NULL,
  `signed_name` varchar(120) DEFAULT NULL,
  `sign_ip` varchar(45) DEFAULT NULL,
  `expires_on` date DEFAULT NULL,
  `withdrawn_at` datetime DEFAULT NULL,
  `withdrawn_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `token` (`token`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_release_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `vendor_agreements` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `vendor` varchar(120) NOT NULL,
  `service` varchar(255) NOT NULL,
  `client_info` varchar(255) NOT NULL DEFAULT '',
  `agreement_status` varchar(20) NOT NULL DEFAULT 'Not signed',
  `signed_on` date DEFAULT NULL,
  `renews_on` date DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `updated_by` int(10) unsigned DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `vendor` (`vendor`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `privacy_incidents` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `kind` varchar(40) NOT NULL,
  `occurred_on` date DEFAULT NULL,
  `discovered_on` date NOT NULL,
  `notice_deadline` date NOT NULL,
  `description` text NOT NULL,
  `info_involved` varchar(500) DEFAULT NULL,
  `risk_nature` text DEFAULT NULL,
  `risk_recipient` text DEFAULT NULL,
  `risk_acquired` text DEFAULT NULL,
  `risk_mitigation` text DEFAULT NULL,
  `risk_level` varchar(40) NOT NULL DEFAULT 'Under assessment',
  `status` varchar(20) NOT NULL DEFAULT 'Open',
  `reported_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `closed_at` datetime DEFAULT NULL,
  `closed_by` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `privacy_incident_clients` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `incident_id` int(10) unsigned NOT NULL,
  `client_id` int(10) unsigned DEFAULT NULL,
  `client_label` varchar(190) NOT NULL,
  `notified_at` date DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `incident_client` (`incident_id`, `client_id`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_pic_incident` FOREIGN KEY (`incident_id`) REFERENCES `privacy_incidents` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_pic_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `privacy_incident_events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `incident_id` int(10) unsigned NOT NULL,
  `event_type` varchar(20) NOT NULL,
  `recipient` varchar(60) DEFAULT NULL,
  `method` varchar(60) DEFAULT NULL,
  `happened_on` date NOT NULL,
  `detail` text NOT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `incident_id` (`incident_id`),
  CONSTRAINT `fk_pie_incident` FOREIGN KEY (`incident_id`) REFERENCES `privacy_incidents` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `amendment_requests` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `track_id` int(10) unsigned NOT NULL,
  `client_id` int(10) unsigned NOT NULL,
  `requested_on` date NOT NULL,
  `sent_to` varchar(190) DEFAULT NULL,
  `hours_requested` decimal(7,2) DEFAULT NULL,
  `amount_requested` decimal(10,2) DEFAULT NULL,
  `new_end_date` date DEFAULT NULL,
  `letter` text DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Awaiting reply',
  `replied_on` date DEFAULT NULL,
  `reply_note` varchar(255) DEFAULT NULL,
  `amendment_id` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `track_id` (`track_id`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_amendreq_track` FOREIGN KEY (`track_id`) REFERENCES `training_tracks` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_amendreq_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `closure_followups` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `client_id` int(10) unsigned NOT NULL,
  `closure_id` int(10) unsigned DEFAULT NULL,
  `interval_days` smallint(5) unsigned NOT NULL,
  `due_on` date NOT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Pending',
  `still_employed` tinyint(1) DEFAULT NULL,
  `still_using_tech` tinyint(1) DEFAULT NULL,
  `independent` tinyint(1) DEFAULT NULL,
  `needs_service` tinyint(1) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `completed_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `client_id` (`client_id`),
  KEY `idx_due` (`status`,`due_on`),
  CONSTRAINT `fk_closefu_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `incoming_authorizations` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `auth_number` varchar(80) NOT NULL,
  `client_name` varchar(190) DEFAULT NULL,
  `service_category` varchar(190) DEFAULT NULL,
  `amount` decimal(10,2) DEFAULT NULL,
  `hours` decimal(7,2) DEFAULT NULL,
  `approved_on` date DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `counselor_name` varchar(120) DEFAULT NULL,
  `counselor_email` varchar(190) DEFAULT NULL,
  `sender_email` varchar(190) DEFAULT NULL,
  `agency` varchar(190) DEFAULT NULL,
  `email_text` mediumtext DEFAULT NULL,
  `source` varchar(20) NOT NULL DEFAULT 'Pasted',
  `message_key` char(64) DEFAULT NULL,
  `client_id` int(10) unsigned DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'New',
  `track_id` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `handled_by` int(10) unsigned DEFAULT NULL,
  `handled_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `message_key` (`message_key`),
  KEY `idx_status` (`status`),
  KEY `auth_number` (`auth_number`),
  KEY `client_id` (`client_id`),
  CONSTRAINT `fk_incauth_client` FOREIGN KEY (`client_id`) REFERENCES `clients` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `portal_request_offers` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `request_id` int(10) unsigned NOT NULL,
  `start_at` datetime NOT NULL,
  `end_at` datetime NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `track_id` int(10) unsigned DEFAULT NULL,
  `is_remote` tinyint(1) NOT NULL DEFAULT 0,
  `location` varchar(190) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'Offered',
  `session_id` int(10) unsigned DEFAULT NULL,
  `created_by` int(10) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `chosen_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `request_id` (`request_id`, `status`),
  CONSTRAINT `fk_offer_request` FOREIGN KEY (`request_id`) REFERENCES `portal_requests` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
CREATE TABLE IF NOT EXISTS `mail_log` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `sent_at` datetime NOT NULL DEFAULT current_timestamp(),
  `recipient_type` varchar(20) NOT NULL DEFAULT 'other',
  `via` varchar(10) NOT NULL DEFAULT 'graph',
  `ok` tinyint(1) NOT NULL DEFAULT 0,
  `with_attachment` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `sent_at` (`sent_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- A starting text for the administrator to edit; nobody is asked to sign it until it is turned on.
SELECT 'Confidentiality agreement', 'Edit this text before turning the agreement on.
# Client information
- I keep everything I learn about clients confidential, during and after my work here.
- I look at a client''s record only when my work needs it.
- I share client information only as the client''s consent, a release of information or the law allows.
# Devices and accounts
- I keep my password and sign-in codes to myself, and lock my computer and phone when I step away.
- I report a lost phone or a possible privacy problem straight away.
# When I leave
- I return or delete client information I hold, and my duty of confidentiality continues.', 0, 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `staff_agreements`);

-- 4.16.0 starting texts, off until edited.
SELECT 'Exit acknowledgement', 'Edit this text before turning the agreement on.
# Before I leave
- I have returned every device, key and badge that belongs to the organisation.
- I have deleted client information from any personal phone, computer or account.
- I have handed over my open work as my supervisor asked.
# After I leave
- My duty to keep client information confidential continues.', 'exit', 0, 0
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `staff_agreements` WHERE `kind` = 'exit');

SELECT 'Privacy training', 'Edit this text before turning the training on.
# Why privacy matters
Clients trust us with their health, disability and work information. Protecting it is part of every job here.
# The rules
- Look at a client record only when your work needs it.
- Share client information only as the client''s consent, a release of information or the law allows.
- Never send client details by text message or to a personal email address.
- Lock your computer and phone whenever you step away.
# If something goes wrong
Report a lost phone, a wrong email, or anything that might expose client information to your supervisor straight away.', '? When may you open a client''s record?
- Whenever you are curious
* When your work needs it
- When a friend asks about them
? A counselor you don''t know phones asking about a client. What do you do?
- Tell them what they ask, since they work in VR
* Check there is a release of information or consent before sharing anything
- Read them the case notes
? You lose your work phone. What do you do?
- Wait a week in case it turns up
* Report it straight away
- Nothing, the app is locked', 1
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `training_modules`);
